// NodOpera · Publicador de redes (n8n Code node). Fuente de workflows/redes-publicador.json (se arma con: node redes/armar.js)
// Lee /data/publicador/hoy.json (lo deja preparar.mjs en Windows a las 8:40) y publica lo mismo en Facebook, Instagram y LinkedIn.
// Tokens SOLO en el .env de n8n: META_TOKEN (system user nodopera-bot) y LINKEDIN_TOKEN. Si falta uno, esa red se omite.
// REDES_MODO=publicar (default) | borrador → Facebook sin publicar (published=false), Instagram crea el contenedor sin media_publish.
const E = $env;
const http = (o) => this.helpers.httpRequest(o);
const d = $json.data ?? $json;
const hoy = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Mexico_City" }).format(new Date());
const estado = $getWorkflowStaticData("global");

if (!d || !d.ok) return [];                       // preparar.mjs ya dejó el error en cola.json
if (d.fecha !== hoy) return [];                   // no se preparó hoy: no se publica nada viejo
if (estado.ultimo === d.id + "@" + hoy) return []; // ya corrió hoy con este item

const MODO = (E.REDES_MODO || "publicar").trim().toLowerCase();
const PUBLICAR = MODO === "publicar";
const G = `https://graph.facebook.com/${E.META_GRAPH_VERSION || "v23.0"}`;
const PAGE_ID = E.FB_PAGE_ID || "1411767948692962";
const ORG = `urn:li:organization:${E.LINKEDIN_ORG_ID || "144103410"}`;
const texto = d.texto, imgs = d.imagenes;
const textoIG = d.texto_instagram || texto; // preparar.mjs: "+ info: link en la bio" en vez del enlace
const espera = (ms) => new Promise((r) => setTimeout(r, ms));
const secretos = [E.META_TOKEN, E.LINKEDIN_TOKEN].filter(Boolean);
const limpio = (e) => {
  let m = (e && (e.response?.body?.error?.message || e.response?.body?.message || e.description || e.message)) || String(e);
  for (const s of secretos) m = m.split(s).join("***");
  return m.slice(0, 500);
};

// ---- Facebook (página) ----
async function facebook(pageToken) {
  const post = (url, body) => http({ method: "POST", url, body: { ...body, access_token: pageToken }, json: true });
  if (imgs.length === 1) {
    const r = await post(`${G}/${PAGE_ID}/photos`, { url: imgs[0], caption: texto, published: PUBLICAR });
    return r.post_id || r.id;
  }
  const fotos = [];
  for (const u of imgs) fotos.push((await post(`${G}/${PAGE_ID}/photos`, { url: u, published: false })).id);
  const r = await post(`${G}/${PAGE_ID}/feed`, { message: texto, attached_media: fotos.map((id) => ({ media_fbid: id })), published: PUBLICAR });
  return r.id;
}

// ---- Instagram (@nodopera.mx) ----
async function instagram(igId) {
  const crear = (b) => http({ method: "POST", url: `${G}/${igId}/media`, body: { ...b, access_token: E.META_TOKEN }, json: true }).then((r) => r.id);
  let cid;
  if (imgs.length === 1) cid = await crear({ image_url: imgs[0], caption: textoIG });
  else {
    const hijos = [];
    for (const u of imgs) hijos.push(await crear({ image_url: u, is_carousel_item: true }));
    cid = await crear({ media_type: "CAROUSEL", children: hijos.join(","), caption: textoIG });
  }
  for (let i = 0; i < 20; i++) {
    const s = await http({ url: `${G}/${cid}`, qs: { fields: "status_code", access_token: E.META_TOKEN }, json: true });
    if (s.status_code === "FINISHED") break;
    if (s.status_code === "ERROR" || s.status_code === "EXPIRED") throw new Error(`Instagram no procesó las imágenes (${s.status_code})`);
    await espera(3000);
  }
  if (!PUBLICAR) return "contenedor:" + cid;
  return (await http({ method: "POST", url: `${G}/${igId}/media_publish`, body: { creation_id: cid, access_token: E.META_TOKEN }, json: true })).id;
}

// ---- LinkedIn (página de empresa; requiere la Community Management API aprobada) ----
// "little text": hay que escapar estos caracteres o LinkedIn corta el texto (el # se deja para que sigan siendo hashtags)
const escLi = (t) => t.replace(/[\\|{}@\[\]()<>*_~]/g, (c) => "\\" + c);
async function linkedin() {
  if (!PUBLICAR) throw new Error("modo borrador: LinkedIn no tiene borradores por API, no se envió");
  const H = { Authorization: `Bearer ${E.LINKEDIN_TOKEN}`, "LinkedIn-Version": E.LINKEDIN_VERSION || "202509", "X-Restli-Protocol-Version": "2.0.0" };
  const urns = [];
  for (const u of imgs) {
    const ini = await http({ method: "POST", url: "https://api.linkedin.com/rest/images?action=initializeUpload", headers: H, body: { initializeUploadRequest: { owner: ORG } }, json: true });
    const bin = await http({ url: u, encoding: "arraybuffer", json: false });
    await http({ method: "PUT", url: ini.value.uploadUrl, headers: { Authorization: H.Authorization, "Content-Type": "application/octet-stream" }, body: Buffer.from(bin), json: false });
    urns.push(ini.value.image);
  }
  const content = urns.length === 1 ? { media: { id: urns[0] } } : { multiImage: { images: urns.map((id) => ({ id })) } };
  const r = await http({
    method: "POST", url: "https://api.linkedin.com/rest/posts", headers: H, json: true, returnFullResponse: true,
    body: { author: ORG, commentary: escLi(texto), visibility: "PUBLIC", lifecycleState: "PUBLISHED", isReshareDisabledByAuthor: false,
      distribution: { feedDistribution: "MAIN_FEED", targetEntities: [], thirdPartyDistributionChannels: [] }, content },
  });
  return r.headers["x-restli-id"] || r.headers["x-linkedin-id"] || "ok";
}

const ids = {}, errores = {}, omitidas = {};
if (E.META_TOKEN) {
  let pagina = null;
  try {
    pagina = await http({ url: `${G}/${PAGE_ID}`, qs: { fields: "access_token,instagram_business_account", access_token: E.META_TOKEN }, json: true });
  } catch (e) { errores.meta = "No pude leer la página con META_TOKEN: " + limpio(e); }
  if (pagina) {
    try { ids.facebook = await facebook(pagina.access_token); } catch (e) { errores.facebook = limpio(e); }
    const ig = E.IG_USER_ID || pagina.instagram_business_account?.id || "17841461732637167";
    if (!ig) errores.instagram = "La página no tiene Instagram conectado (o el token no tiene instagram_basic)";
    else { try { ids.instagram = await instagram(ig); } catch (e) { errores.instagram = limpio(e); } }
  }
} else omitidas.facebook = omitidas.instagram = "Falta META_TOKEN en el .env de n8n";
if (E.LINKEDIN_TOKEN) { try { ids.linkedin = await linkedin(); } catch (e) { errores.linkedin = limpio(e); } }
else omitidas.linkedin = "Falta LINKEDIN_TOKEN: publicar a mano desde Chrome con el texto de hoy.json";

estado.ultimo = d.id + "@" + hoy;
const algo = Object.keys(ids).length > 0;
const r = {
  id: d.id, fecha: hoy, modo: MODO,
  estado: !algo ? (Object.keys(errores).length ? "error" : "preparado") : Object.keys(errores).length ? "parcial" : (PUBLICAR ? "publicado" : "borrador"),
  ids, errores, omitidas,
  ...(!algo && !Object.keys(errores).length ? { nota: "Sin tokens: no se publicó en ninguna red" } : {}),
};
r.aviso = [
  `NodOpera · redes ${hoy} · ${d.id} → ${r.estado.toUpperCase()} (modo ${MODO})`,
  ...Object.entries(ids).map(([k, v]) => `✅ ${k}: ${v}`),
  ...Object.entries(errores).map(([k, v]) => `❌ ${k}: ${v}`),
  ...Object.entries(omitidas).map(([k, v]) => `⏭️ ${k}: ${v}`),
  "", "Texto:", texto, "", "Imágenes:", ...imgs,
].join("\n");
return [{ json: r }];
